774	// ---- 持久化 ----
775	
776	// loadLocked 读取、严格解析并重放校验状态文件。调用方必须持锁。
777	func (s *Store) loadLocked() (*storedState, error) {
778		raw, err := os.ReadFile(s.path)
779		if err != nil {
780			return nil, err
781		}
782		if len(bytes.TrimSpace(raw)) == 0 {
783			return nil, fmt.Errorf("%w: %s: file is empty", ErrStateCorrupt, s.path)
784		}
785		// 先于结构扫描与解码逐字节校验字符串：非法 UTF-8 与未配对代理项转义
786		// 会被 encoding/json 悄悄改写成 U+FFFD 且不报错，必须在此明确拒绝，
787		// 使被改写的编号/账户名/动作原文不可能参与后续任何匹配与重放。
788		if err := checkStrictStrings(raw); err != nil {
789			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
790		}
791		if err := checkStateStructure(raw); err != nil {
792			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
793		}
794		var state storedState
795		dec := json.NewDecoder(bytes.NewReader(raw))
796		dec.DisallowUnknownFields()
797		if err := dec.Decode(&state); err != nil {
798			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
799		}
800		// 拒绝单个合法 JSON 之后再拼接的额外内容（如 "{} {}"）。
801		var extra json.RawMessage
802		if err := dec.Decode(&extra); err != io.EOF {
803			if err == nil {
804				err = fmt.Errorf("unexpected trailing content after state document: %s", strings.TrimSpace(string(extra)))
805			}
806			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
807		}
808		if err := validateState(&state); err != nil {
809			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
810		}
811		return &state, nil
812	}
813	
814	// commitLocked 序列化状态并以“临时文件 + fsync + 原子改名 + 目录 fsync”提交。
815	// 任一步失败都保留上次完整状态。调用方必须持锁。
816	func (s *Store) commitLocked(state *storedState) error {
817		if err := validateState(state); err != nil {
818			return fmt.Errorf("refusing to persist invalid state: %w", err)
819		}
820		payload, err := json.MarshalIndent(state, "", "  ")
821		if err != nil {
822			return err
823		}
824		payload = append(payload, '\n')
825	
826		dir := filepath.Dir(s.path)
827		tmp, err := os.CreateTemp(dir, ".govflow-state-*")
828		if err != nil {
829			return err
830		}
831		tmpName := tmp.Name()
832		cleanup := func() { _ = os.Remove(tmpName) }
833		if _, err := tmp.Write(payload); err != nil {
834			_ = tmp.Close()
835			cleanup()
836			return err
837		}
838		if err := tmp.Sync(); err != nil {
839			_ = tmp.Close()
840			cleanup()
841			return err
842		}
843		if err := tmp.Close(); err != nil {
844			cleanup()
845			return err
846		}
847		if err := os.Chmod(tmpName, 0o600); err != nil {
848			cleanup()
849			return err
850		}
851		if err := os.Rename(tmpName, s.path); err != nil {
852			cleanup()
853			return err
854		}
855		if err := syncDir(dir); err != nil {
856			return err
857		}
858		return nil
859	}
860	
861	func syncDir(dir string) error {
862		d, err := os.Open(dir)
863		if err != nil {
864			return err
865		}
866		defer d.Close()
867		return d.Sync()
868	}
869	
870	// validateState 做结构校验并重放全部凭据，确认余额与凭据完全一致。
871	func validateState(state *storedState) error {
872		if state.Magic != stateMagic {
873			return fmt.Errorf("bad magic %q", state.Magic)
874		}
875		if state.Version != stateVersion {
876			return fmt.Errorf("unsupported state version %d", state.Version)
877		}
878		if state.InitialTreasury < 0 {
879			return errors.New("initial treasury balance is negative")
880		}
881		if state.Treasury < 0 {
882			return errors.New("treasury balance is negative")
883		}
884		if state.Balances == nil {
885			return errors.New("balances table is missing")
886		}
887		if state.Proposals == nil {
888			return errors.New("proposals table is missing")
889		}
890		if state.Receipts == nil {
891			return errors.New("receipts table is missing")
892		}
893		// VoteProposals 缺省视为空表：旧版本写出的状态文件不含投票提案，继续可读。
894		if state.VoteProposals == nil {
895			state.VoteProposals = map[string]*storedVoteProposal{}
896		}
897		for account, balance := range state.Balances {
898			if account == "" {
899				return errors.New("balance entry with empty account")
900			}
901			if balance < 0 {
902				return fmt.Errorf("balance of %q is negative", account)
903			}
904		}
905		for key, p := range state.Proposals {
906			if p == nil {
907				return fmt.Errorf("proposal %q is empty", key)
908			}
909			if p.ID != key || p.ID == "" {
910				return fmt.Errorf("proposal key %q does not match id %q", key, p.ID)
911			}
912			if p.State != "passed" && p.State != "executed" {
913				return fmt.Errorf("proposal %q has unknown state %q", p.ID, p.State)
914			}
915			// 动作原文登记时原样保存；空串或非法原文留待执行时拒绝。
916		}
917		if err := validateVoteProposals(state); err != nil {
918			return err
919		}
920	
921		// 重放凭据：从初始资金库余额出发，按成功顺序重放每笔转账，
922		// 校验凭据内的前后余额、最终资金库与各账户余额，并检查状态一致性。
923		simTreasury := state.InitialTreasury
924		simBalances := map[string]int64{}
925		seenReceipts := map[string]int{}
926		for order, rcpt := range state.Receipts {
927			if rcpt == nil {
928				return fmt.Errorf("receipt %d is empty", order)
929			}
930			// order 是执行留痕中明确保存的成功提交序号（0 起），必须显式写出、
931			// 为 int64 范围内的非负整数且恰好等于凭据在记录表中的位置：第一份
932			// 凭据缺 order 也不能补成 0。缺失/空值/类型不符/位置不符都带提案
933			// 编号与字段报损坏，不按数组位置重新编号。
934			if err := validateReceiptOrder(order, rcpt); err != nil {
935				return err
936			}
937			if prev, dup := seenReceipts[rcpt.ProposalID]; dup {
938				return fmt.Errorf("duplicate receipt for %q at positions %d and %d", rcpt.ProposalID, prev, order)
939			}
940			seenReceipts[rcpt.ProposalID] = order
941			ownerState, ownerTimelock, ownerActions, found := proposalOwnerState(state, rcpt.ProposalID)
942			if !found {
943				return fmt.Errorf("receipt %q references an unregistered proposal", rcpt.ProposalID)
944			}
945			if ownerState != "executed" {
946				return fmt.Errorf("proposal %q has receipt but state is %q", rcpt.ProposalID, ownerState)
947			}
948			// 保存的凭据与首次执行受同一条执行资格规则约束：executed_at 必须明确
949			// 写出且不得早于提案时间锁。登记提案与投票提案共用这一判断。
950			if err := validateReceiptExecutedAt(order, rcpt, ownerTimelock); err != nil {
951				return err
952			}
953			// 每项动作的 index 与四个余额字段（资金库/收款账户 × before/after）
954			// 都必须明确写出：任何一个缺失、为 null 或类型不符都判整份状态损坏，
955			// 不能按数组位置、转账金额、账户余额或其它凭据补出；明确写出的 0 是
956			// 合法记录（第一项动作的 index 0 必须显式保存）。
957			for i := range rcpt.Actions {
958				if err := validateReceiptActionIndex(rcpt.ProposalID, i, &rcpt.Actions[i]); err != nil {
959					return err
960				}
961				if err := validateReceiptActionBalances(rcpt.ProposalID, i, &rcpt.Actions[i]); err != nil {
962					return err
963				}
964			}
965			// 凭据声明的逐笔转账由统一转账规则（verifyReceiptTransfers）重放
966			// 核对：动作条数/编号/原文、资金库与收款账户前后余额任一不符都带
967			// 动作位置报损坏原因；本函数随即返回错误，整份状态被拒绝，重放结果
968			// 不会被查询或落盘采纳。
969			var verr error
970			simTreasury, verr = verifyReceiptTransfers(rcpt, ownerActions, simTreasury, simBalances)
971			if verr != nil {
972				return verr
973			}
974		}
975		if simTreasury != state.Treasury {
976			return fmt.Errorf("treasury balance %d does not match receipt replay %d", state.Treasury, simTreasury)
977		}
978		// 余额表的账户集合必须与成功凭据涉及的收款账户完全一致：缺少收款账户、
979		// 出现无凭据支持的账户（即使写成 0）或已记录余额不符都判整份状态损坏。
980		// 不能只按账户数量或仅遍历文件自身的键：把一个已收款账户换成数量相同、
981		// 余额写成 0 的陌生账户时，数量相等且缺失键在 map 中读到零值，会被误判
982		// 为合法。账户名排序后报告，使错误信息确定且可读；余额表的排列顺序本身
983		// 不影响判定。
984		savedAccounts := make([]string, 0, len(state.Balances))
985		for account := range state.Balances {
986			savedAccounts = append(savedAccounts, account)
987		}
988		replayAccounts := make([]string, 0, len(simBalances))
989		for account := range simBalances {
990			replayAccounts = append(replayAccounts, account)
991		}
992		sort.Strings(savedAccounts)
993		sort.Strings(replayAccounts)
994		var missing, unexpected []string
995		si, ri := 0, 0
996		for si < len(savedAccounts) || ri < len(replayAccounts) {
997			switch {
998			case ri == len(replayAccounts) || (si < len(savedAccounts) && savedAccounts[si] < replayAccounts[ri]):
999				unexpected = append(unexpected, savedAccounts[si])
1000				si++
1001			case si == len(savedAccounts) || savedAccounts[si] > replayAccounts[ri]:
1002				missing = append(missing, replayAccounts[ri])
1003				ri++
1004			default:
1005				si++
1006				ri++
1007			}
1008		}
1009		if len(missing) > 0 || len(unexpected) > 0 {
1010			problems := ""
1011			if len(missing) > 0 {
1012				problems = fmt.Sprintf("missing recipient account(s) %s with no balance record for funds actually received",
1013					strings.Join(quoteAccounts(missing), ", "))
1014			}
1015			if len(unexpected) > 0 {
1016				if problems != "" {
1017					problems += "; "
1018				}
1019				problems += fmt.Sprintf("account(s) %s have balance records but no successful receipt supports them (a zero balance does not make an unsupported account legal)",
1020					strings.Join(quoteAccounts(unexpected), ", "))
1021			}
1022			return fmt.Errorf("balance table is inconsistent with execution receipts: %s", problems)
1023		}
1024		for _, account := range replayAccounts {
1025			if balance := state.Balances[account]; balance != simBalances[account] {
1026				return fmt.Errorf("balance of %q is %d but receipt replay yields %d", account, balance, simBalances[account])
1027			}
1028		}
1029		// 已执行的提案必须有凭据；passed 提案不得有凭据（上面已部分保证）。
1030		for _, p := range state.Proposals {
1031			_, hasReceipt := seenReceipts[p.ID]
1032			if p.State == "executed" && !hasReceipt {
1033				return fmt.Errorf("proposal %q is executed without receipt", p.ID)
1034			}
1035		}
1036		for _, p := range state.VoteProposals {
1037			_, hasReceipt := seenReceipts[p.ID]
1038			if p.State == "executed" && !hasReceipt {
1039				return fmt.Errorf("voting proposal %q is executed without receipt", p.ID)
1040			}
1041		}
1042		return nil
1043	}
1044	
1045	// quoteAccounts 给账户名列表逐个加上 Go 风格引号，便于在损坏原因中逐字定位。
1046	func quoteAccounts(accounts []string) []string {
1047		quoted := make([]string, len(accounts))
1048		for i, account := range accounts {
1049			quoted[i] = strconv.Quote(account)
1050		}
1051		return quoted
1052	}
1053	
1054	// validateReceiptExecutedAt 严格判定一份已保存凭据的 executed_at：
1055	// 字段未写出、显式为 null 或不是 int64 整数都返回带定位的错误；
1056	// 明确写出的值必须不早于所属提案的 timelock_end（恰好等于时间锁有效，
1057	// 时间锁允许 0 时明确写出的 0 同样有效）。order 是凭据在凭据表中的
1058	// 位置（0 起），与提案编号一起用于定位。
1059	// “缺失/空值/类型不符”的判定与逐票明细、计票结果共用同一份规则
1060	// （requiredScalarProblem），此处只补充凭据的业务位置与执行资格检查。
1061	func validateReceiptExecutedAt(order int, rcpt *Receipt, timelockEnd int64) error {
1062		if problem := requiredScalarProblem(rcpt.executedAtRaw, scalarInteger); problem != "" {
1063			return fmt.Errorf("receipt %d for proposal %q field %q %s", order, rcpt.ProposalID, "executed_at", problem)
1064		}
1065		if rcpt.ExecutedAt < timelockEnd {
1066			return fmt.Errorf("receipt %d for proposal %q executed_at %d is before timelock_end %d",
1067				order, rcpt.ProposalID, rcpt.ExecutedAt, timelockEnd)
1068		}
1069		return nil
1070	}
1071	
1072	// validateReceiptOrder 严格判定一份已保存凭据的 order：它是执行留痕中明确
1073	// 保存的成功提交序号（0 起），字段未写出、显式为 null 或不是 int64 整数都
1074	// 返回带提案编号与字段的错误；类型合法但值与凭据在记录表中的实际位置不符
1075	// （含负数）则返回位置不符的错误。第一份凭据恰好排在位置 0 也不能因此把
1076	// 缺失字段补成 0——明确写出的 0 才是合法序号，缺失/null/写错类型一律拒绝。
1077	// position 是凭据在凭据表中的位置（0 起）。
1078	func validateReceiptOrder(position int, rcpt *Receipt) error {
1079		if problem := requiredScalarProblem(rcpt.orderRaw, scalarInteger); problem != "" {
1080			return fmt.Errorf("receipt %d for proposal %q field %q %s",
1081				position, rcpt.ProposalID, "order", problem)
1082		}
1083		if rcpt.Order != int64(position) {
1084			return fmt.Errorf("receipt %d for proposal %q field %q is %d, expected %d",
1085				position, rcpt.ProposalID, "order", rcpt.Order, position)
1086		}
1087		return nil
1088	}
1089	
1090	// validateReceiptActionIndex 严格判定一条动作留痕的 index：它是该动作在所属
1091	// 凭据中明确保存的位置编号（0 起）。字段未写出、显式为 null 或不是 int64
1092	// 整数（字符串、布尔、小数、指数写法、超界）返回带提案编号、动作位置与
1093	// 字段的错误；类型合法但值与动作的实际位置不符（含负数）返回位置不符错误。
1094	// 第一项动作缺失 index 不得被补成 0：只有明确写出的 0 才合法。position 是
1095	// 动作在凭据 actions 中的位置（0 起）。
1096	func validateReceiptActionIndex(id string, position int, ar *ActionReceipt) error {
1097		if problem := requiredScalarProblem(ar.indexRaw, scalarInteger); problem != "" {
1098			return fmt.Errorf("receipt for proposal %q action %d field %q %s",
1099				id, position, "index", problem)
1100		}
1101		if ar.Index != int64(position) {
1102			return fmt.Errorf("receipt for proposal %q action %d field %q is %d, expected %d",
1103				id, position, "index", ar.Index, position)
1104		}
1105		return nil
1106	}
1107	
1108	// validateReceiptActionBalances 严格判定一条动作留痕的四个余额字段：
1109	// 资金库与收款账户两侧的 before/after 都必须明确写出、非 null 且为 int64
1110	// 整数。任何一个字段缺失都判整份状态损坏，不能根据转账金额、账户余额或
1111	// 其它凭据补出它——即使按其余记录推算该字段本来应为 0。明确写出的整数 0
1112	// 是合法记录（如资金库恰好扣到 0、收款账户首次收款前为 0），不得当成缺失。
1113	// index 是动作在凭据中的下标（0 起），与提案编号、所在侧一起用于定位。
1114	// “缺失/空值/类型不符”的判定与逐票明细、计票结果、executed_at 共用同一份
1115	// 规则（validateRawFields），此处只补充业务位置：提案编号 + 动作下标 + 侧。
1116	func validateReceiptActionBalances(id string, index int, ar *ActionReceipt) error {
1117		sides := []struct {
1118			name   string
1119			update *BalanceUpdate
1120		}{
1121			{"treasury", &ar.Treasury},
1122			{"recipient", &ar.Recipient},
1123		}
1124		for _, side := range sides {
1125			err := validateRawFields([]rawField{
1126				{name: "before", kind: scalarInteger, raw: side.update.beforeRaw},
1127				{name: "after", kind: scalarInteger, raw: side.update.afterRaw},
1128			}, func(field, problem string) error {
1129				return fmt.Errorf("receipt for proposal %q action %d %s field %q %s",
1130					id, index, side.name, field, problem)
1131			})
1132			if err != nil {
1133				return err
1134			}
1135		}
1136		return nil
1137	}
1138	
1139	// ---- 结构检查：固定字段名逐字匹配 + 重复键拒绝 ----
1140	
1141	// schemaKind 是状态文件 JSON 在某一层的形状类别。
1142	type schemaKind int
1143	
1144	const (
1145		kindAny     schemaKind = iota // 叶子值：结构检查不深入，类型由解码器核对
1146		kindObject                    // 固定字段对象：键必须与保存格式的字段名逐字一致
1147		kindMap                       // 业务编号表：键是自由文本（账户名、提案编号）
1148		kindArray                     // 数组
1149		kindString                    // 叶子：必须是 JSON 字符串
1150		kindBoolean                   // 叶子：必须是 JSON 布尔值（不接受字符串/数字/null）
1151		kindInteger                   // 叶子：必须是 int64 范围内的 JSON 整数（不接受小数/指数/字符串/null）
1152	)
1153	
1154	// schemaNode 描述状态文件某一层允许的形状。整棵树由 storedState 的 json tag
1155	// 反射生成，字段名集合因此永远与保存格式一致，不会随结构演进而漂移。
1156	type schemaNode struct {
1157		kind   schemaKind
1158		fields map[string]*schemaNode // kindObject：字段名 → 值的形状
1159		elem   *schemaNode            // kindMap/kindArray：值/元素的形状
1160	}
1161	
1162	// schemaOf 按 encoding/json 的字段名规则（json tag 优先，缺省用字段名）推导形状。
1163	func schemaOf(t reflect.Type) *schemaNode {
1164		for t.Kind() == reflect.Pointer {
1165			t = t.Elem()
1166		}
1167		switch t.Kind() {
1168		case reflect.Struct:
1169			node := &schemaNode{kind: kindObject, fields: map[string]*schemaNode{}}
1170			for i := 0; i < t.NumField(); i++ {
1171				f := t.Field(i)
1172				if f.PkgPath != "" { // 未导出字段不参与 JSON
1173					continue
1174				}
1175				name := f.Name
1176				if tag, ok := f.Tag.Lookup("json"); ok {
1177					tagName, _, _ := strings.Cut(tag, ",")
1178					if tagName == "-" {
1179						continue
1180					}
1181					if tagName != "" {
1182						name = tagName
1183					}
1184				}
1185				node.fields[name] = schemaOf(f.Type)
1186			}
1187			return node
1188		case reflect.Map:
1189			return &schemaNode{kind: kindMap, elem: schemaOf(t.Elem())}
1190		case reflect.Slice, reflect.Array:
1191			return &schemaNode{kind: kindArray, elem: schemaOf(t.Elem())}
1192		case reflect.String:
1193			return &schemaNode{kind: kindString}
1194		case reflect.Bool:
1195			return &schemaNode{kind: kindBoolean}
1196		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
1197			reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
1198			return &schemaNode{kind: kindInteger}
1199		default:
1200			return &schemaNode{kind: kindAny}
1201		}
1202	}
1203	
1204	var storedStateSchema = schemaOf(reflect.TypeOf(storedState{}))
1205	
1206	func init() {
1207		// 票据的四个标量字段（representative/weight/support/voted_at）由
1208		// validateStoredBallot 逐票判定“缺失/空值/类型不符”，其错误原因需要带上
1209		// 提案编号、票据下标与字段名；因此结构扫描在这些叶子位置保持宽松（kindAny），
1210		// 不抢在解码器之前用不含票据定位的通用信息报错。
1211		ballotFields := storedStateSchema.fields["vote_proposals"].elem.fields["ballots"].elem.fields
1212		for _, name := range []string{"representative", "weight", "support", "voted_at"} {
1213			ballotFields[name].kind = kindAny
1214		}
1215		// 计票结果的两个权重字段（for_weight/against_weight）同理：缺失/空值/
1216		// 类型不符的判定需要带上提案编号，统一由 validateStoredTally 报错，
1217		// 结构扫描在这两个叶子位置保持宽松。tallied_at 保持严格整数叶子，
1218		// 其“不早于截止”的既有校验不变。
1219		tallyFields := storedStateSchema.fields["vote_proposals"].elem.fields["tally"].fields
1220		for _, name := range []string{"for_weight", "against_weight"} {
1221			tallyFields[name].kind = kindAny
1222		}
1223		// 凭据的 executed_at 同理：缺失/空值/类型不符/早于时间锁的判定需要带上
1224		// 提案编号与凭据位置，统一由 validateReceiptExecutedAt 报错，结构扫描在此
1225		// 叶子位置保持宽松。
1226		receiptFields := storedStateSchema.fields["receipts"].elem.fields
1227		receiptFields["executed_at"].kind = kindAny
1228		// 凭据的 order 同理：缺失/空值/类型不符/位置不符的判定需要带上提案编号与
1229		// 凭据位置，统一由 validateReceiptOrder 报错，结构扫描在此叶子位置保持宽松。
1230		receiptFields["order"].kind = kindAny
1231		// 凭据逐笔留痕的 index 同理：缺失/空值/类型不符/位置不符的判定需要带上
1232		// 提案编号与动作下标，统一由 validateReceiptActionIndex 报错，结构扫描在
1233		// 此叶子位置保持宽松。
1234		receiptFields["actions"].elem.fields["index"].kind = kindAny
1235		// 凭据逐笔留痕的四个余额字段（treasury/recipient 的 before/after）同理：
1236		// 缺失/空值/类型不符的判定需要带上提案编号、动作下标与所在侧，统一由
1237		// validateReceiptActionBalances 报错，结构扫描在这些叶子位置保持宽松。
1238		actionFields := receiptFields["actions"].elem.fields
1239		for _, side := range []string{"treasury", "recipient"} {
1240			balanceFields := actionFields[side].fields
1241			balanceFields["before"].kind = kindAny
1242			balanceFields["after"].kind = kindAny
1243		}
1244	}
1245	
1246	// scanFrame 是结构扫描的栈帧。
1247	type scanFrame struct {
1248		node    *schemaNode
1249		isArray bool
1250		opaque  bool // 形状不符或叶子位置的容器：只配对括号，类型错误交给解码器报告
1251		seen    map[string]bool
1252		atValue bool // 对象帧：下一个待消费 token 是值而非键
1253		index   int  // 数组帧：下一个元素下标
1254		path    string
1255	}
1256	
1257	func peekFrame(stack []*scanFrame) *scanFrame {
1258		if len(stack) == 0 {
1259			return nil
1260		}
1261		return stack[len(stack)-1]
1262	}
1263	
1264	// checkStateStructure 在解码前逐 token 扫描状态文件：
1265	//   - 同一对象内键（按 JSON 解读后的字符串，转义拼写与普通拼写视为同一键）不得重复；
1266	//   - 固定字段对象的键必须与保存格式的字段名逐字一致：大小写变体（如 Treasury、
1267	//     Support）与未知字段一样拒绝，避免解码器的大小写折叠把两份值并入同一字段；
1268	//   - balances/proposals/vote_proposals 等业务编号表的键是自由文本，
1269	//     Audit 与 audit、GIP-1 与 gip-1 是不同账户/编号，不做字段名检查。
1270	//
1271	// 报错带有出问题的字段与所在记录的路径（如 vote_proposals["GIP-1"].ballots[0]），
1272	// 便于定位。字段顺序、缩进与合法转义不影响判定。
1273	func checkStateStructure(raw []byte) error {
1274		dec := json.NewDecoder(bytes.NewReader(raw))
1275		// UseNumber：数字 token 保留词面写法，整数叶子可据此精确判定 int64 范围，
1276		// 不被 float64 在 2^63 附近的舍入混淆（MaxInt64 与 MaxInt64+1 会折成同一浮点）。
1277		dec.UseNumber()
1278		var stack []*scanFrame
1279		// 对象帧读到键时，把该键对应值的形状与路径暂存于此，供紧随其后的值使用。
1280		pendingNode := storedStateSchema
1281		pendingPath := "state"
1282	
1283		// 一个值消费完毕：推进父帧的键/值位置或数组下标。
1284		finishValue := func() {
1285			top := peekFrame(stack)
1286			if top == nil || top.opaque {
1287				return
1288			}
1289			if top.isArray {
1290				top.index++
1291			} else {
1292				top.atValue = false
1293			}
1294		}
1295	
1296		for {
1297			tok, err := dec.Token()
1298			if err == io.EOF {
1299				if len(stack) != 0 {
1300					return errors.New("unterminated object or array")
1301				}
1302				return nil
1303			}
1304			if err != nil {
1305				return err
1306			}
1307	
1308			if top := peekFrame(stack); top != nil && top.opaque {
1309				// 不透明容器内不做字段检查，只配对括号。
1310				if d, ok := tok.(json.Delim); ok {
1311					if d == '{' || d == '[' {
1312						stack = append(stack, &scanFrame{opaque: true})
1313					} else {
1314						stack = stack[:len(stack)-1]
1315						finishValue()
1316					}
1317				}
1318				continue
1319			}
1320	
1321			if top := peekFrame(stack); top != nil && !top.isArray && !top.atValue {
1322				// 对象帧的键位置：闭括号或下一个键。
1323				if d, ok := tok.(json.Delim); ok {
1324					if d != '}' {
1325						return fmt.Errorf("unexpected %q inside object at %s", string(d), top.path)
1326					}
1327					stack = stack[:len(stack)-1]
1328					finishValue()
1329					continue
1330				}
1331				key, ok := tok.(string)
1332				if !ok {
1333					return errors.New("object key must be a string")
1334				}
1335				if top.seen[key] {
1336					return fmt.Errorf("duplicate key %q at %s", key, top.path)
1337				}
1338				top.seen[key] = true
1339				top.atValue = true
1340				switch top.node.kind {
1341				case kindObject:
1342					child, known := top.node.fields[key]
1343					if !known {
1344						return fmt.Errorf("unknown field %q at %s", key, top.path)
1345					}
1346					pendingNode = child
1347					pendingPath = top.path + "." + key
1348				case kindMap:
1349					// 业务编号是自由文本，大小写变体属于不同编号，不得拒绝或合并。
1350					pendingNode = top.node.elem
1351					pendingPath = top.path + "[" + strconv.Quote(key) + "]"
1352				}
1353				continue
1354			}
1355	
1356			// 值位置：对象键之后的值或数组元素。
1357			node := pendingNode
1358			path := pendingPath
1359			if top := peekFrame(stack); top != nil && top.isArray {
1360				node = top.node.elem
1361				path = top.path + "[" + strconv.Itoa(top.index) + "]"
1362			}
1363			if d, ok := tok.(json.Delim); ok {
1364				switch d {
1365				case '{', '[':
1366					frame := &scanFrame{isArray: d == '[', path: path}
1367					shapeOK := (d == '{' && (node.kind == kindObject || node.kind == kindMap)) ||
1368						(d == '[' && node.kind == kindArray)
1369					if !shapeOK {
1370						// 叶子位置出现容器或形状不符：跳过内容，类型错误由解码器报告。
1371						frame.opaque = true
1372					} else {
1373						frame.node = node
1374						if d == '{' {
1375							frame.seen = map[string]bool{}
1376						}
1377					}
1378					stack = append(stack, frame)
1379				default: // '}' 或 ']'：数组结束（对象的闭括号已在键位置处理）
1380					if len(stack) == 0 {
1381						return errors.New("unexpected closing delimiter")
1382					}
1383					stack = stack[:len(stack)-1]
1384					finishValue()
1385				}
1386				continue
1387			}
1388			// 标量值（含 null）：严格叶子必须与字段声明的 JSON 类型逐字一致，
1389			// null 不允许用来顶替字符串/布尔/整数。
1390			if err := checkLeafScalar(node, path, tok); err != nil {
1391				return err
1392			}
1393			finishValue()
1394		}
1395	}
1396	
1397	// leafKindName 是严格叶子类型在错误信息中的人类可读名称。
1398	func leafKindName(k schemaKind) string {
1399		switch k {
1400		case kindString:
1401			return "string"
1402		case kindBoolean:
1403			return "boolean"
1404		case kindInteger:
1405			return "integer"
1406		default:
1407			return "value"
1408		}
1409	}
1410	
1411	// tokenKindName 归类一个标量 token 实际写出的 JSON 类型。
1412	func tokenKindName(tok json.Token) string {
1413		switch v := tok.(type) {
1414		case nil:
1415			return "null"
1416		case string:
1417			return "string"
1418		case bool:
1419			return "boolean"
1420		case json.Number:
1421			if _, err := strconv.ParseInt(string(v), 10, 64); err == nil {
1422				return "integer"
1423			}
1424			return "number"
1425		default:
1426			return "value"
1427		}
1428	}
1429	
1430	// checkLeafScalar 校验严格标量叶子：字符串/布尔/int64 整数位置出现 null 或
1431	// 其它 JSON 类型即判结构损坏。非整数（小数、指数）或超出 int64 的整数同样拒绝。
1432	func checkLeafScalar(node *schemaNode, path string, tok json.Token) error {
1433		switch node.kind {
1434		case kindString, kindBoolean, kindInteger:
1435		default:
1436			return nil
1437		}
1438		if node.kind == kindInteger {
1439			if n, ok := tok.(json.Number); ok {
1440				if _, err := strconv.ParseInt(string(n), 10, 64); err != nil {
1441					return fmt.Errorf("field at %s must be an int64 integer, got %s", path, string(n))
1442				}
1443				return nil
1444			}
1445		}
1446		want := leafKindName(node.kind)
1447		if got := tokenKindName(tok); got != want {
1448			return fmt.Errorf("field at %s must be %s, got %s", path, want, got)
1449		}
1450		return nil
1451	}
1452

